def header(tag, title, note='Leadership working session · November 2026'):
    return f'''<div class="top-stripe"></div><div class="slide-header"><div><div class="slide-tag">{tag}</div><h2>{title}</h2></div><div><img src="{logo}" alt="Rev.io"><div class="header-note">{note}</div></div></div>'''

def slide(n, tag, title, body, note='Leadership working session · November 2026'):
    return f'''<section class="slide" id="slide-{n}">{header(tag,title,note)}<div class="slide-body leadership-body">{body}</div></section>'''

def metric(label, value, sub='', cls=''):
    return f'<div class="kpi {cls}"><span>{label}</span><strong>{value}</strong><em>{sub}</em></div>'

def card(title, text, eyebrow='RECOMMENDED ANSWER', cls=''):
    return f'<div class="card answer-card {cls}"><div class="mini-eyebrow">{eyebrow}</div><h3>{title}</h3><div class="answer-copy">{text}</div></div>'

