prefix=prefix.replace('</head>',custom+'</head>')
labels=['Cover','Answer Map','Funnel','2027 Plan','Q4 Forecast','Forecast Cadence','Contract Timing','Parity + Packaging','Suite Enablement','CSA Scorecard','Leadership Capacity','SE + Channel','Staffing','Lead Generation','Decisions']
suffix=re.sub(r'const TOTAL = \d+;',f'const TOTAL = {len(slides)};',suffix)
suffix=re.sub(r"const labels = \[[^;]+;",'const labels = '+repr(labels).replace("'",'"')+';',suffix)
suffix=re.sub(r'<span class="nav-counter" id="nav-counter">[^<]+</span>',f'<span class="nav-counter" id="nav-counter">1 / {len(slides)}</span>',suffix)
suffix=suffix.replace('<div class="nav-title">H2 Leadership Offsite</div>','<div class="nav-title">Leadership Offsite · 2027 Sales Operating Plan</div>')
out=prefix+'<div class="deck">\n'+'\n'.join(slides)+'\n</div>\n'+suffix
OUTPUT.write_text(out)
print(OUTPUT)
print('slides',len(slides))
